INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Bugfixing nur nach der Entwicklung nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch währenddessen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Bugfixing?', 3, '[{"text": "Fehler im Code beheben", "correct": true, "because": "Stellt Funktion sicher"}, {"text": "UI verschönern", "correct": false, "because": "Kein Designfokus"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Bugfixing?', 5, '[{"text": "Fehlerkorrektur", "correct": true, "because": "Behebt das Problem"}, {"text": "Validierung", "correct": true, "because": "Prüft Erfolg"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkoptimierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bugfixing braucht Tests. b) Fehler sind immer sofort sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Fehler oft versteckt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Bugfixing?', 4, '[{"text": "Fehlerursache", "correct": false, "because": "Muss gefunden werden"}, {"text": "Validierung", "correct": false, "because": "Sichert Lösung"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bugfixing ohne Tests möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Aber riskant"}, {"text": "Nein", "correct": false, "because": "Technisch machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich zur Fehlerkorrektur?', 3, '[{"text": "Code anpassen", "correct": true, "because": "Behebt den Bug"}, {"text": "UI neu laden", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Server neustarten", "correct": false, "because": "Keine direkte Lösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Bugfixing?', 5, '[{"text": "Stabilität", "correct": true, "because": "Reduziert Fehler"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bugfixing braucht Validierung. b) Es behebt immer alle Fehler. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht alle Fehler lösbar"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Bugfixing?', 4, '[{"text": "Fehlerbeschreibung", "correct": false, "because": "Zeigt Problem"}, {"text": "Testumgebung", "correct": false, "because": "Prüft Lösung"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Bugfixing nur für große Fehler?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Bugs wichtig"}, {"text": "Ja", "correct": false, "because": "Alle Größen relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutze ich zur Validierung?', 4, '[{"text": "Tests durchführen", "correct": true, "because": "Prüft Funktion"}, {"text": "Log-Analyse", "correct": true, "because": "Bestätigt Erfolg"}, {"text": "UI-Refresh", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bugfixing die Performance senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann sie verbessern"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Bugfixing?', 3, '[{"text": "Fehlerursache finden", "correct": true, "because": "Sichert Lösung"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bugfixing behebt Fehler. b) Validierung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Validierung essenziell"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Validierung?', 5, '[{"text": "Neue Fehler", "correct": true, "because": "Fix nicht geprüft"}, {"text": "Falsche Lösung", "correct": true, "because": "Problem bleibt"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Bugfixing unwichtig?', 3, '[{"text": "Fehlerreproduktion", "correct": false, "because": "Zeigt Problem"}, {"text": "Testnachweis", "correct": false, "because": "Bestätigt Fix"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Bugfixing ohne Tests erfolgen?', 3, '[{"text": "Ja", "correct": true, "because": "Aber unsicher"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bugfixing immer dokumentiert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Sollte, aber nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Praxisabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich zur Validierung?', 4, '[{"text": "Unit-Tests", "correct": true, "because": "Prüft korrigierte Funktion"}, {"text": "UI-Editor", "correct": false, "because": "Designbezogen"}, {"text": "Netzwerkscanner", "correct": false, "because": "Anderer Fokus"}]');
